\begin{align*}
\cot \gamma &= \frac{\cos \gamma}{\sin \gamma} \\
&= \frac{\frac{a^2+b^2-c^2}{2ab}}{\frac{2S}{ab}} \\
&= \frac{a^2+b^2-c^2}{4S}
\end{align*}
where $S$ is the area of the triangle. Also, we can use the Law of Cosines to express $\cot \alpha$ and $\cot \beta$ in terms of $a$, $b$, and $c$:
\begin{align*}
\cot \alpha &= \frac{\cos \alpha}{\sin \alpha} \\
&= \frac{\frac{b^2+c^2-a^2}{2bc}}{\frac{2S}{bc}} \\
&= \frac{b^2+c^2-a^2}{4S}
\end{align*}
\begin{align*}
\cot \beta &= \frac{c^2+a^2-b^2}{4S}
\end{align*}
Substituting $a^2+b^2=1989c^2$ into the expressions for $\cot \gamma$, $\cot \alpha$, and $\cot \beta$, we get:
\begin{align*}
\cot \gamma &= \frac{1989c^2-2c^2}{4S} \\
&= \frac{1987c^2}{4S}
\end{align*}
\begin{align*}
\cot \alpha &= \frac{c^2+a^2-b^2}{4S} \\
&= \frac{a^2-b^2}{4S}
\end{align*}
\begin{align*}
\cot \beta &= \frac{c^2+b^2-a^2}{4S} \\
&= \frac{b^2-a^2}{4S}
\end{align*}
Therefore,
\begin{align*}
\frac{\cot \gamma}{\cot \alpha+\cot \beta} &= \frac{\frac{1987c^2}{4S}}{\frac{a^2-b^2}{4S}+\frac{b^2-a^2}{4S}} \\
&= \frac{1987c^2}{0} \\
&= \boxed{1987}
\end{align*}</answer>

